import { Component } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { VirtualScrollArea } from "#core/ui-next/components/virtual-scroll-area.jsx";

export const VirtualScrollAreaExample: Component = () => {
	const items = [...Array(100_000).keys()];
	return (
		<VirtualScrollArea
			class="w-1\/3 h-96 m-2 p-2 border border-secondary-3"
			itemWidth={136}
			itemHeight={48}
			each={items}
		>
			{(item: number) => (
				<div class="w-32 h-10 m-2 p-2 border border-secondary-3 flex flex-row">
					<Icon
						class="size-8 -mt-1"
						name="LEADER_BENJAMIN_FRANKLIN"
					/>
					{item}
				</div>
			)}
		</VirtualScrollArea>
	);
};
